IF OBJECT_ID('dbo.Zipcodes', 'U') IS NOT NULL DROP TABLE dbo.Zipcodes;
IF OBJECT_ID('dbo.Cities', 'U') IS NOT NULL DROP TABLE dbo.Cities;

CREATE TABLE dbo.Zipcodes (
    Zipcode CHAR(5) PRIMARY KEY
);

CREATE TABLE dbo.Cities (
    CityID INT PRIMARY KEY IDENTITY(1,1),
    CityName NVARCHAR(100) NOT NULL
);

-- Insert sample data
INSERT INTO dbo.Zipcodes (Zipcode) VALUES ('12345'), ('23456'), ('34567');
INSERT INTO dbo.Cities (CityName) VALUES ('Springfield'), ('Shelbyville'), ('Ogdenville');

-- Verification
SELECT * FROM dbo.Zipcodes;
SELECT * FROM dbo.Cities;

IF OBJECT_ID('dbo.Customers', 'U') IS NOT NULL DROP TABLE dbo.Customers;

CREATE TABLE dbo.Customers (
    CustomerID INT PRIMARY KEY IDENTITY(1,1),
    CustomerName NVARCHAR(100) NOT NULL,
    Zipcode CHAR(5) NOT NULL,
    CityID INT NOT NULL,
    CONSTRAINT FK_Customers_Zipcodes FOREIGN KEY (Zipcode) REFERENCES dbo.Zipcodes(Zipcode),
    CONSTRAINT FK_Customers_Cities FOREIGN KEY (CityID) REFERENCES dbo.Cities(CityID)
);

-- Verification
SELECT * FROM sys.foreign_keys WHERE parent_object_id = OBJECT_ID('dbo.Customers');

INSERT INTO dbo.Customers (CustomerName, Zipcode, CityID) VALUES
('John Doe', '12345', 1),
('Jane Smith', '23456', 2),
('Jim Brown', '34567', 3);

-- Verify inserts
SELECT * FROM dbo.Customers;
